const minimalImpl =
    await viem.deployContract(
        "HardhatMinimalUUPS"
    );


const proxy =
    await viem.deployContract(
        "ERC1967Proxy",
        [
            minimalImpl.address,
            encodeInitializeWithAddress(
                zeroAddress
            )
        ]
    );


const realImpl =
    await viem.deployContract(
        "IdentityRegistryUpgradeable"
    );


const minimalProxy =
    await viem.getContractAt(
        "HardhatMinimalUUPS",
        proxy.address
    );


await minimalProxy
    .write
    .upgradeToAndCall(
        [
            realImpl.address,
            "0x8129fc1c"
        ]
    );


const identityRegistry =
    await viem.getContractAt(
        "IdentityRegistryUpgradeable",
        proxy.address
    );


const burnEthTransferConstraint =
    requirement ===
        null
        ? null
        : (() => {

            const matches =
                requirement.constraints.filter(
                    constraint =>
                        constraint.participantSide ===
                            "B" &&
                        constraint.basis ===
                            "SOLIDITY_REQUIRE_STATEMENT" &&
                        constraint.containerSymbol ===
                            "ERC8060Reference" &&
                        typeof constraint.rawText ===
                            "string" &&
                        constraint.rawText.includes(
                            "ETH transfer failed"
                        ) &&
                        typeof constraint.locator?.filePath ===
                            "string" &&
                        constraint.locator.filePath.endsWith(
                            "ERC8060Reference.sol"
                        ) &&
                        constraint.locator.startLine ===
                            94 &&
                        constraint.locator.endLine ===
                            94
                );


            if (
                matches.length !==
                1
            ) {

                throw new Error(
                    "Expected exactly one ERC-8060 burn ETH transfer constraint at pinned locator 94."
                );

            }


            return matches[0];

        })();


